function rulesFor(baskets, minSup, minConf) {
  const N = baskets.length;
  const counts = {};
  const single = {};
  for (const b of baskets) {
    const items = [...new Set(b)];
    for (const it of items) single[it] = (single[it] || 0) + 1;
    for (let i = 0; i < items.length; i++)
      for (let j = i + 1; j < items.length; j++) {
        const k = items[i] + '|' + items[j];
        counts[k] = (counts[k] || 0) + 1;
      }
  }
  const out = [];
  for (const [k, n] of Object.entries(counts)) {
    const sup = n / N;
    const conf = n / single[k.split('|')[0]];
    if (sup >= minSup && conf >= minConf) out.push(k + ' s=' + sup.toFixed(2) + ' c=' + conf.toFixed(2));
  }
  return out;
}
const baskets = [['shoes', 'socks'], ['shoes', 'socks'], ['shoes', 'hat'], ['socks', 'hat']];
console.log('gated=' + JSON.stringify(rulesFor(baskets, 0.25, 0.5)));
console.log('strict=' + JSON.stringify(rulesFor(baskets, 0.5, 0.9)));

